    ctx.font = "600 25px Segoe UI";
    ctx.fillText("USAF 1951 · TARGET SINTETICO", 65, 70);
    const cells = 3,
      w = 290;
    for (let row = 0; row < 3; row++)
      for (let col = 0; col < 3; col++) {
        const ox = 65 + col * w,
          oy = 140 + row * 280,
          pitch = 16 / 2 ** ((row * 3 + col) / 4);
        ctx.fillStyle = "#111";
        ctx.font = "20px Segoe UI";
        ctx.fillText(`G ${row} / E ${col + 1}`, ox, oy - 25);
        for (let k = 0; k < 3; k++) {
          ctx.fillRect(ox + k * 2 * pitch, oy, pitch, 6 * pitch);
          ctx.fillRect(ox + 145, oy + k * 2 * pitch, 6 * pitch, pitch);
        }
      }
    ctx.font = "18px Segoe UI";
