let pending;
function loadScript(path) {
  return new Promise((resolve, reject) => {
    const script = document.createElement("script");
    script.src = new URL(
      path,
      new URL(import.meta.env.BASE_URL, document.baseURI),
    ).href;
    script.onload = resolve;
    script.onerror = () =>
      reject(Error("Impossibile caricare il decoder TIFF locale."));
    document.head.append(script);
  });
}
export function ensureTiffDecoder() {
  if (globalThis.UTIF) return Promise.resolve();
  if (!pending)
    pending = loadScript("vendor/pako.min.js")
      .then(() => loadScript("vendor/UTIF.js"))
      .catch((error) => {
        pending = null;
        throw error;
      });
  return pending;
}
