export const format = (value, digits = 3) =>
  Number.isFinite(value)
    ? value.toLocaleString("it-IT", { maximumFractionDigits: digits })
    : "—";
export const waveNames = {
  "double-slit": "Doppia fenditura",
  "double-hole": "Due fori circolari",
  "single-slit": "Fenditura singola",
  "single-hole": "Disco di Airy",
};
export function downloadBlob(blob, name) {
  const url = URL.createObjectURL(blob),
    link = document.createElement("a");
  link.href = url;
  link.download = name;
  link.click();
  setTimeout(() => URL.revokeObjectURL(url), 10000);
}
export function downloadCanvas(canvas, name) {
  return new Promise((resolve, reject) =>
    canvas.toBlob((blob) => {
      if (!blob) {
        reject(Error("Esportazione non riuscita."));
        return;
      }
      downloadBlob(blob, name);
      resolve();
    }, "image/png"),
  );
}
export function downloadJSON(value, name) {
  downloadBlob(
    new Blob([JSON.stringify(value, null, 2)], { type: "application/json" }),
    name,
  );
}
export const escapeXML = (value) =>
  String(value).replace(
    /[&<>"']/g,
    (ch) =>
      ({
        "&": "&amp;",
        "<": "&lt;",
        ">": "&gt;",
        '"': "&quot;",
        "'": "&apos;",
      })[ch],
  );
export function makeReport({
  title,
  params,
  metrics = [],
  panels,
  width = 2400,
}) {
  const canvas = document.createElement("canvas");
  canvas.width = width;
  canvas.height = Math.round(width * 0.8);
  const c = canvas.getContext("2d"),
    s = width / 1800;
  c.scale(s, s);
  c.fillStyle = "#0b1017";
  c.fillRect(0, 0, 1800, 1440);
  c.fillStyle = "#79dfc7";
  c.font = "26px Segoe UI";
  c.fillText(title, 50, 56);
  c.fillStyle = "#b1c0cf";
  c.font = "16px Segoe UI";
  c.fillText(metrics.join(" · "), 50, 92);
  const text = JSON.stringify(params);
  c.fillText(text.slice(0, 170), 50, 122);
  panels.slice(0, 6).forEach((panel, i) => {
    const x = 50 + (i % 3) * 575,
      y = 175 + Math.floor(i / 3) * 585,
      w = 550,
      h = 520;
    c.fillStyle = "#92a3b4";
    c.font = "16px Segoe UI";
    c.fillText(panel.title, x, y - 15);
    c.fillStyle = "#111923";
    c.fillRect(x, y, w, h);
    if (panel.canvas) {
      const ratio = Math.min(w / panel.canvas.width, h / panel.canvas.height),
        rw = panel.canvas.width * ratio,
        rh = panel.canvas.height * ratio;
      c.drawImage(panel.canvas, x + (w - rw) / 2, y + (h - rh) / 2, rw, rh);
    }
  });
  c.fillStyle = "#92a3b4";
  c.font = "15px Segoe UI";
  c.fillText(
    "Ottica Studio · calcolo locale · intensità relative · parametri completi nella sessione JSON",
    50,
    1390,
  );
  return canvas;
}
export function reportSVG({
  title,
  params,
  panels,
  series = [],
  xMax = 1,
  xLabel = "x",
  yLabel = "Intensità relativa",
}) {
  let svg = `<svg xmlns="http://www.w3.org/2000/svg" width="1800" height="1200" viewBox="0 0 1800 1200"><metadata>${escapeXML(JSON.stringify(params))}</metadata><rect width="1800" height="1200" fill="#0b1017"/><text x="50" y="60" fill="#79dfc7" font-family="sans-serif" font-size="26">${escapeXML(title)}</text>`;
  panels.slice(0, 4).forEach((p, i) => {
    if (!p.canvas) return;
    const x = 50 + i * 435;
    svg += `<text x="${x}" y="110" fill="#92a3b4" font-family="sans-serif" font-size="15">${escapeXML(p.title)}</text><image x="${x}" y="130" width="410" height="410" preserveAspectRatio="xMidYMid meet" href="${p.canvas.toDataURL("image/png")}"/>`;
  });
  const left = 90,
    top = 640,
    w = 1610,
    h = 390,
    points = series.flatMap((s) => s.data),
    min = Math.min(0, ...points.map((p) => p.x)),
    max = xMax || Math.max(...points.map((p) => p.x), 1),
    yMax = Math.max(1, ...points.map((p) => p.y));
  series.forEach((line, i) => {
    const x = 90 + (i % 3) * 550,
      y = 560 + Math.floor(i / 3) * 22;
    svg += `<path d="M${x},${y - 5}h22" stroke="${line.color}" stroke-width="3"/><text x="${x + 30}" y="${y}" fill="#b1c0cf" font-family="sans-serif" font-size="13">${escapeXML(line.label)}</text>`;
  });
  for (let i = 0; i <= 6; i++) {
    const x = left + (i * w) / 6,
      value = min + ((max - min) * i) / 6;
    svg += `<path d="M${x},${top}v${h}" stroke="#263340"/><text x="${x}" y="1060" text-anchor="middle" fill="#92a3b4" font-family="sans-serif" font-size="14">${Number(value.toPrecision(4))}</text>`;
  }
  for (let i = 0; i <= 4; i++) {
    const y = top + h - (i * h) / 4;
    svg += `<path d="M${left},${y}H${left + w}" stroke="#263340"/><text x="${left - 15}" y="${y + 5}" text-anchor="end" fill="#92a3b4" font-family="sans-serif" font-size="14">${((i * yMax) / 4).toFixed(2)}</text>`;
  }
  for (const line of series) {
    let path = "";
    for (const [i, p] of line.data.entries())
      if (p.x <= max)
        path +=
          (i ? "L" : "M") +
          (left + ((p.x - min) / (max - min)) * w).toFixed(2) +
          "," +
          (top + h - (p.y / yMax) * h).toFixed(2);
    svg += `<path d="${path}" stroke="${line.color}" stroke-width="2" fill="none"/>`;
  }
  svg += `<text x="900" y="1090" fill="#92a3b4" text-anchor="middle" font-family="sans-serif" font-size="17">${escapeXML(xLabel)} · ${escapeXML(yLabel)}</text><text x="50" y="1160" fill="#92a3b4" font-family="sans-serif" font-size="14">Curve vettoriali; mappe e immagini raster incorporate. Parametri nei metadati.</text></svg>`;
  return new Blob([svg], { type: "image/svg+xml;charset=utf-8" });
}
