import { useRef, useState } from "react";
import { Save, Upload, Download, Trash2 } from "lucide-react";
import { useStudioStore } from "../../store/useStudioStore.js";
import { parseSession } from "../../services/schemas.js";
import { decodeFile } from "../../services/zernike/images.js";
import { downloadJSON } from "../../utils/export.js";
import { Help, help } from "../ui/Controls.jsx";
import { useToast } from "../ui/Toast.jsx";
export function PresetManager({ engine }) {
  const store = useStudioStore(),
    toast = useToast(),
    [name, setName] = useState(""),
    [selected, setSelected] = useState(""),
    file = useRef(null),
    library = useRef(null);
  function save() {
    try {
      const preset = store.savePreset(name, engine);
      setName("");
      setSelected(preset.id);
      toast("Preset salvato nel browser.");
    } catch (e) {
      toast(e.message);
    }
  }
  async function loadSession(event) {
    try {
      const input = event.target.files[0];
      if (!input) return;
      if (input.size > 28e6)
        throw Error("Sessione troppo grande (massimo 28 MB).");
      const session = parseSession(JSON.parse(await input.text()));
      let image = null;
      if (session.image) {
        const blob = await (await fetch(session.image)).blob();
        image = await decodeFile(
          new File([blob], "sessione.png", { type: "image/png" }),
        );
      }
      if (image) store.setUploadedImage(image);
      store.setState(session.engine, session.state);
      location.hash = `/${session.engine}`;
      toast("Sessione caricata.");
    } catch (e) {
      toast(e.message);
    } finally {
      event.target.value = "";
    }
  }
  function saveSession() {
    try {
      let image = null;
      if (
        engine === "zernike" &&
        store.zernike.target === "upload" &&
        store.uploadedImage
      ) {
        const source = store.uploadedImage,
          c = document.createElement("canvas"),
          scale = Math.min(1, 1024 / Math.max(source.width, source.height));
        c.width = Math.round(source.width * scale);
        c.height = Math.round(source.height * scale);
        c.getContext("2d").drawImage(source, 0, 0, c.width, c.height);
        image = c.toDataURL("image/png");
      }
      downloadJSON(
        {
          format: "ottica-studio-session",
          version: 1,
          engine,
          state: store[engine],
          image,
        },
        `ottica-${engine}-sessione.json`,
      );
    } catch (e) {
      toast(e.message);
    }
  }
  return (
    <section className="sidebar-section">
      <div className="section-heading">
        <h3>Preset personali e sessioni</h3>
        <Help
          entry={help(
            "Archivio locale",
            "I preset conservano i parametri in questo browser; le sessioni JSON possono essere trasferite.",
            "Salvare non modifica la simulazione. Un preset non incorpora la foto utente; una sessione la conserva fino a 1024 px.",
            "Esporta una copia prima di cancellare i dati del browser. Nessun file viene inviato a server.",
          )}
        />
      </div>
      <div className="input-action">
        <input
          aria-label="Nome del preset"
          placeholder="Nome del nuovo preset"
          maxLength={80}
          value={name}
          onChange={(e) => setName(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === "Enter" && name.trim()) save();
          }}
        />
        <Help
          entry={help(
            "Nome del preset",
            "Etichetta personale per riconoscere una configurazione ottica.",
            "Cambiare il nome non modifica la simulazione; Salva crea un nuovo record locale.",
            "Scegli un nome che descriva il fenomeno e la condizione, ad esempio Young 532 nm.",
          )}
        />
        <button
          className="icon-button"
          aria-label="Salva preset"
          disabled={!name.trim()}
          onClick={save}
        >
          <Save size={17} />
        </button>
      </div>
      <div className="input-action">
        <select
          aria-label="Preset personali"
          value={selected}
          onChange={(e) => {
            setSelected(e.target.value);
            if (e.target.value) {
              try {
                store.applyPreset(e.target.value);
              } catch (error) {
                toast(error.message);
              }
            }
          }}
        >
          <option value="">Seleziona un preset…</option>
          {store.presets
            .filter((p) => p.engine === engine)
            .map((p) => (
              <option key={p.id} value={p.id}>
                {p.name}
              </option>
            ))}
        </select>
        <Help
          entry={help(
            "Preset personali",
            "Configurazioni salvate per questo laboratorio nel browser.",
            "Selezionare un preset sostituisce i parametri; il cestino elimina soltanto il record selezionato.",
            "Esporta la libreria JSON per trasferirla ad altri dispositivi.",
          )}
        />
        <button
          className="icon-button"
          disabled={!selected}
          aria-label="Elimina preset selezionato"
          onClick={() => {
            store.deletePreset(selected);
            setSelected("");
          }}
        >
          <Trash2 size={16} />
        </button>
      </div>
      <div className="button-grid">
        <button className="button small" onClick={saveSession}>
          <Save size={14} /> Salva sessione
        </button>
        <button className="button small" onClick={() => file.current.click()}>
          <Upload size={14} /> Carica sessione
        </button>
        <button
          className="button small"
          onClick={() => downloadJSON(store.presets, "ottica-preset.json")}
        >
          <Download size={14} /> Esporta preset
        </button>
        <button
          className="button small"
          onClick={() => library.current.click()}
        >
          <Upload size={14} /> Importa preset
        </button>
      </div>
      <input
        ref={file}
        type="file"
        accept="application/json,.json"
        hidden
        onChange={loadSession}
      />
      <input
        ref={library}
        type="file"
        accept="application/json,.json"
        hidden
        onChange={async (e) => {
          try {
            const f = e.target.files[0];
            if (f) {
              if (f.size > 1e6) throw Error("Libreria troppo grande.");
              store.importPresets(JSON.parse(await f.text()));
              toast("Preset importati.");
            }
          } catch (error) {
            toast(error.message);
          }
          e.target.value = "";
        }}
      />
    </section>
  );
}
