import { forwardRef, useLayoutEffect, useRef } from "react";
import {
  Chart,
  LineController,
  LineElement,
  PointElement,
  LinearScale,
  Tooltip,
  Legend,
  Filler,
} from "chart.js";
Chart.register(
  LineController,
  LineElement,
  PointElement,
  LinearScale,
  Tooltip,
  Legend,
  Filler,
);
export const LineChart = forwardRef(function LineChart(
  { series, xLabel, yLabel, xMax, yMax, theme = "dark" },
  ref,
) {
  const canvas = useRef(null),
    chart = useRef(null);
  useLayoutEffect(() => {
    const text = theme === "dark" ? "#9aabbb" : "#526575",
      grid = theme === "dark" ? "#273341" : "#e1e8eb";
    chart.current = new Chart(canvas.current, {
      type: "line",
      plugins: [
        {
          id: "canvasBackground",
          beforeDraw(chart) {
            const { ctx, width, height } = chart;
            ctx.save();
            ctx.globalCompositeOperation = "destination-over";
            ctx.fillStyle = theme === "dark" ? "#111923" : "#ffffff";
            ctx.fillRect(0, 0, width, height);
            ctx.restore();
          },
        },
      ],
      data: {
        datasets: series.map((s) => ({
          ...s,
          data: s.data,
          borderWidth: s.borderWidth || 1.8,
          pointRadius: 0,
          tension: 0,
          fill: false,
        })),
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        parsing: false,
        normalized: true,
        interaction: { mode: "nearest", axis: "x", intersect: false },
        scales: {
          x: {
            type: "linear",
            max: xMax,
            grid: { color: grid },
            ticks: { color: text, maxTicksLimit: 8 },
            title: { display: true, text: xLabel, color: text },
          },
          y: {
            min: 0,
            max: yMax,
            grid: { color: grid },
            ticks: { color: text, maxTicksLimit: 6 },
            title: { display: true, text: yLabel, color: text },
          },
        },
        plugins: {
          legend: {
            labels: {
              color: text,
              usePointStyle: true,
              boxWidth: 8,
              font: { size: 11 },
            },
          },
          tooltip: {
            callbacks: {
              label: (c) => `${c.dataset.label}: ${c.parsed.y.toPrecision(4)}`,
            },
          },
        },
      },
    });
    return () => chart.current?.destroy();
  }, [series, xLabel, yLabel, xMax, yMax, theme]);
  return (
    <div className="chart-container">
      <canvas
        role="img"
        aria-label={`${yLabel} in funzione di ${xLabel}`}
        ref={(node) => {
          canvas.current = node;
          if (typeof ref === "function") ref(node);
          else if (ref) ref.current = node;
        }}
      />
    </div>
  );
});
