import { useEffect, useRef, useState } from "react";
import {
  SimulationClient,
  releaseResult,
} from "../services/SimulationClient.js";
const createWave = () =>
  new Worker(new URL("../services/wave/renderer.worker.js", import.meta.url), {
    type: "module",
  });
const createZernike = () =>
  new Worker(
    new URL("../services/zernike/compute.worker.js", import.meta.url),
    { type: "module" },
  );
export function useSimulation(
  engine,
  params,
  context,
  { enabled = true, forceCPU = false } = {},
) {
  const client = useRef(null),
    [result, setResult] = useState(null),
    [busy, setBusy] = useState(true),
    [error, setError] = useState(null),
    [backend, setBackend] = useState(
      engine === "wave" ? "Worker · Fraunhofer" : "Inizializzazione FFT",
    );
  useEffect(() => {
    const instance = new SimulationClient(
      engine === "wave" ? createWave() : createZernike(),
      {
        onResult: setResult,
        onBusy: setBusy,
        onError: setError,
        onBackend: setBackend,
      },
    );
    client.current = instance;
    if (engine === "zernike") instance.initialize(forceCPU);
    return () => {
      instance.dispose();
      client.current = null;
    };
  }, [engine, forceCPU]);
  useEffect(() => {
    if (enabled) {
      setError(null);
      client.current?.request(params, context);
    } else {
      setBusy(false);
    }
  }, [params, context, enabled, forceCPU]);
  useEffect(() => () => releaseResult(result), [result]);
  return {
    result,
    busy,
    error,
    backend,
    exportData: (kind) => client.current?.exportData(kind),
  };
}
