/** Pure display helpers. Linear intensities remain unchanged in the engines. */
export function heat(t) {
  t = Math.min(1, Math.max(0, t));
  const stops = [
    [2, 4, 9],
    [38, 39, 111],
    [52, 178, 179],
    [121, 223, 199],
    [255, 247, 201],
  ];
  const q = t * 4,
    i = Math.min(3, Math.floor(q)),
    f = q - i;
  return stops[i].map((v, k) => Math.round(v + (stops[i + 1][k] - v) * f));
}
export function diverging(t) {
  t = Math.min(1, Math.max(-1, t));
  const center = [235, 242, 245],
    edge = t < 0 ? [78, 121, 238] : [235, 103, 71],
    f = Math.abs(t);
  return center.map((v, k) => Math.round(v + (edge[k] - v) * f));
}
export function srgbToLinear(v) {
  return v <= 0.04045 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4;
}
export function linearToSrgb(v) {
  v = Math.max(0, Math.min(1, v));
  return v <= 0.0031308 ? 12.92 * v : 1.055 * v ** (1 / 2.4) - 0.055;
}
export function rgbaWave(map, limit = null) {
  const max = limit ?? Math.max(Math.abs(map.min), Math.abs(map.max), 0.01),
    out = new Uint8ClampedArray(map.size * map.size * 4);
  for (let i = 0; i < map.data.length; i++) {
    const w = map.data[i];
    const c = Number.isFinite(w) ? diverging(w / max) : [7, 13, 21];
    out.set(c, i * 4);
    out[i * 4 + 3] = 255;
  }
  return { out, max };
}
