import { forwardRef, useLayoutEffect, useRef } from "react";
import { paintSource } from "../../utils/canvas.js";
import { rgbaWave } from "../../services/zernike/visual.js";
export const CanvasImage = forwardRef(function CanvasImage(
  {
    source,
    label,
    className = "",
    onWheel,
    onPointerDown,
    onPointerMove,
    onPointerUp,
  },
  ref,
) {
  const inner = useRef(null);
  useLayoutEffect(() => {
    paintSource(inner.current, source);
  }, [source]);
  return (
    <canvas
      ref={(node) => {
        inner.current = node;
        if (typeof ref === "function") ref(node);
        else if (ref) ref.current = node;
      }}
      role="img"
      aria-label={label}
      className={`scientific-canvas ${className}`}
      onWheel={onWheel}
      onPointerDown={onPointerDown}
      onPointerMove={onPointerMove}
      onPointerUp={onPointerUp}
      onPointerCancel={onPointerUp}
    />
  );
});
export const WaveMap = forwardRef(function WaveMap(
  { map, label = "Fronte d’onda sulla pupilla", limit },
  ref,
) {
  const inner = useRef(null);
  useLayoutEffect(() => {
    if (!map) return;
    const { out } = rgbaWave(map, limit);
    const canvas = inner.current;
    canvas.width = canvas.height = map.size;
    canvas
      .getContext("2d")
      .putImageData(new ImageData(out, map.size, map.size), 0, 0);
  }, [map, limit]);
  return (
    <div className="wave-map">
      <canvas
        ref={(node) => {
          inner.current = node;
          if (typeof ref === "function") ref(node);
          else if (ref) ref.current = node;
        }}
        className="scientific-canvas"
        role="img"
        aria-label={label}
      />
      <span className="axis-x">x →</span>
      <span className="axis-y">y ↑</span>
      <div className="colorbar">
        <span>
          −
          {(
            limit ||
            Math.max(Math.abs(map?.min || 0), Math.abs(map?.max || 0)) ||
            1
          ).toFixed(2)}{" "}
          λ
        </span>
        <i />
        <span>
          +
          {(
            limit ||
            Math.max(Math.abs(map?.min || 0), Math.abs(map?.max || 0)) ||
            1
          ).toFixed(2)}{" "}
          λ
        </span>
      </div>
    </div>
  );
});
