import { Download, Camera } from "lucide-react";
export function ExportBar({
  disabled,
  onPNG,
  onCSV,
  onSVG,
  onScreenshot,
  extra,
}) {
  return (
    <div className="export-bar" aria-label="Esportazioni">
      <button className="button small" disabled={disabled} onClick={onPNG}>
        <Download size={15} /> PNG
      </button>
      <button className="button small" disabled={disabled} onClick={onCSV}>
        <Download size={15} /> CSV
      </button>
      {onSVG && (
        <button className="button small" disabled={disabled} onClick={onSVG}>
          <Download size={15} /> SVG
        </button>
      )}
      {onScreenshot && (
        <button
          className="button small"
          disabled={disabled}
          onClick={onScreenshot}
        >
          <Camera size={15} /> Report
        </button>
      )}
      {extra}
    </div>
  );
}
