/** One active job and one replaceable pending job: dragging a slider never
 * creates a long queue. The UI owns delivered images; discarded ones are closed. */
export function releaseResult(result) {
  Object.values(result?.images || {}).forEach((image) => image?.close?.());
  result?.extra?.psf?.close?.();
  result?.extra?.result?.close?.();
}
export class SimulationClient {
  constructor(worker, { onResult, onError, onBusy, onBackend } = {}) {
    this.worker = worker;
    this.callbacks = { onResult, onError, onBusy, onBackend };
    this.nextId = 0;
    this.active = null;
    this.pending = null;
    this.imageRevision = null;
    this.exports = new Map();
    this.disposed = false;
    worker.onmessage = (event) => this.receive(event.data);
    worker.onerror = (event) => {
      if (!this.disposed) {
        this.active = null;
        this.pending = null;
        onBusy?.(false);
        onError?.(event.message || "Errore del calcolo in background.");
      }
    };
  }
  initialize(forceCPU = false) {
    this.worker.postMessage({ type: "init", forceCPU });
  }
  request(params, context = {}) {
    if (this.disposed) return;
    this.pending = { id: ++this.nextId, params, context };
    this.callbacks.onBusy?.(true);
    this.dispatch();
  }
  dispatch() {
    if (this.active || !this.pending || this.disposed) return;
    const job = this.pending;
    this.pending = null;
    this.active = job;
    const image = job.context.image;
    if (image && image.revision !== this.imageRevision) {
      const data = image.data.slice();
      this.worker.postMessage(
        { type: "image", size: image.size, buffer: data.buffer },
        [data.buffer],
      );
      this.imageRevision = image.revision;
    }
    this.worker.postMessage(
      job.context.wave
        ? {
            id: job.id,
            p: job.params,
            width: job.context.width,
            height: job.context.height,
            components: job.params.dual,
          }
        : {
            type: "compute",
            id: job.id,
            p: job.params,
            view: job.context.view || "lab",
          },
    );
  }
  receive(data) {
    if (this.disposed) {
      releaseResult(data);
      return;
    }
    if (data.type === "backend" || data.type === "ready") {
      this.callbacks.onBackend?.(data.backend);
      return;
    }
    if (data.type === "error" && this.exports.has(data.id)) {
      const request = this.exports.get(data.id);
      this.exports.delete(data.id);
      request.reject(Error(data.message || "Esportazione non riuscita."));
      return;
    }
    if (data.type === "export") {
      const request = this.exports.get(data.id);
      this.exports.delete(data.id);
      request?.resolve(data);
      return;
    }
    if (!this.active) return;
    const job = this.active;
    this.active = null;
    if (this.pending) {
      // Deliver completed snapshots during animation instead of starving the UI.
      if (data.type === "invalid" || data.type === "error") releaseResult(data);
      else
        this.callbacks.onResult?.({
          ...data,
          params: job.params,
          source: job.context.image?.canvas,
          view: job.context.view || "lab",
        });
      this.dispatch();
      return;
    }
    this.callbacks.onBusy?.(false);
    if (data.type === "invalid" || data.type === "error") {
      this.callbacks.onError?.(data.message || "Risultato non disponibile.");
      return;
    }
    this.callbacks.onError?.(null);
    this.callbacks.onResult?.({
      ...data,
      params: job.params,
      source: job.context.image?.canvas,
      view: job.context.view || "lab",
    });
  }
  exportData(kind = "psf") {
    if (this.active || this.pending)
      return Promise.reject(Error("Attendi la fine del calcolo."));
    const id = ++this.nextId;
    return new Promise((resolve, reject) => {
      this.exports.set(id, { resolve, reject });
      this.worker.postMessage({ type: "export", kind, id });
    });
  }
  dispose() {
    this.disposed = true;
    this.worker.terminate();
    this.pending = null;
    this.active = null;
    for (const item of this.exports.values())
      item.reject(Error("Simulatore chiuso."));
    this.exports.clear();
  }
}
